(172954, 9781, 4625, '<td valign="top">Nice use of the new picture size rule. THe shot looks a bit out of focus, and the icicles aren''t the prettiest I''ve seen, but overall not bad.</td>', 'Nice use of the new picture size rule. THe shot looks a bit out of focus, and the icicles aren''t the prettiest I''ve seen, but overall not bad.', '2002-12-16 01:15:55.000000', NULL, 1),
(172955, 9654, 4625, '<td valign="top">The layout of this shot is great. I think I might have liked this one in color too. The greens would have looked great. great shot well done.</td>', 'The layout of this shot is great. I think I might have liked this one in color too. The greens would have looked great. great shot well done.', '2002-12-16 01:16:40.000000', NULL, 1),
