(172998, 9590, 4625, '<td valign="top">I like the red. The shot could be slightly crisper overall, and the border should have been the same size all around (it''s a bit bigger on the bottom than it is on the top).  I do like hte layout the size is very fitting.</td>', 'I like the red. The shot could be slightly crisper overall, and the border should have been the same size all around (it''s a bit bigger on the bottom than it is on the top).  I do like hte layout the size is very fitting.', '2002-12-16 01:41:16.000000', NULL, 1),
(172999, 9711, 4510, '<td valign="top">Visually interesting.</td>', 'Visually interesting.', '2002-12-16 01:42:08.000000', NULL, 1),
(173000, 9680, 4625, '<td valign="top">I like the christmas feeling in this one. And hte one holly berry showing being the only red to contrast a lot of green works well.</td>', 'I like the christmas feeling in this one. And hte one holly berry showing being the only red to contrast a lot of green works well.', '2002-12-16 01:42:09.000000', NULL, 1),
(173002, 9772, 4510, '<td valign="top">Good use of DOF, well composed, interesting subject, great colours a good shot.</td>', 'Good use of DOF, well composed, interesting subject, great colours a good shot.', '2002-12-16 01:44:16.000000', NULL, 1),
