(173399, 9758, 327, '<td valign="top">Neat shot.....or I should say shots....very neat. What is that bird doing..? Eating??</td>', 'Neat shot.....or I should say shots....very neat. What is that bird doing..? Eating??', '2002-12-16 13:46:06.000000', NULL, 1),
(173400, 9790, 327, '<td valign="top">Frog? Very neat shot.</td>', 'Frog? Very neat shot.', '2002-12-16 13:46:46.000000', NULL, 1),
(173401, 9809, 327, '<td valign="top">Nice color, not crazy for this focus, but love the colors and light.</td>', 'Nice color, not crazy for this focus, but love the colors and light.', '2002-12-16 13:47:16.000000', NULL, 1),
(173402, 9774, 327, '<td valign="top">Hum, just nice....really nice shot. I love the composition and the way the eye has to move here. WELL done. Good light.........no, wonderful light.</td>', 'Hum, just nice....really nice shot. I love the composition and the way the eye has to move here. WELL done. Good light.........no, wonderful light.', '2002-12-16 13:48:05.000000', NULL, 1),
