(173405, 9772, 327, '<td valign="top">Wow, wonderful colors. Maybe a better crop here, but love the colors.</td>', 'Wow, wonderful colors. Maybe a better crop here, but love the colors.', '2002-12-16 13:49:59.000000', NULL, 1),
(173406, 9636, 327, '<td valign="top">Very nice composition, color.....very good work.</td>', 'Very nice composition, color.....very good work.', '2002-12-16 13:50:22.000000', NULL, 1),
