(173410, 9768, 327, '<td valign="top">My. Good eye, good color. I don''t like the crop and the composition. Nice all the same.</td>', 'My. Good eye, good color. I don''t like the crop and the composition. Nice all the same.', '2002-12-16 13:52:32.000000', NULL, 1),
(173411, 9643, 327, '<td valign="top">Pretty, good color and good composition.</td>', 'Pretty, good color and good composition.', '2002-12-16 13:53:01.000000', NULL, 1),
(173413, 9766, 327, '<td valign="top">Stark where ever this is...</td>', 'Stark where ever this is...', '2002-12-16 13:53:31.000000', NULL, 1),
