(175232, 9758, 3540, '<td valign="top">I don''t like the way this was done.  Hard to tell anything about the photographs when then are this small. - Inspzil</td>', 'I don''t like the way this was done.  Hard to tell anything about the photographs when then are this small. - Inspzil', '2002-12-19 07:01:50.000000', NULL, 1),
(175236, 9655, 3540, '<td valign="top">Everything looks real good here except the sky.  I think a polarizing filter would''ve helped a lot. - Inspzil</td>', 'Everything looks real good here except the sky.  I think a polarizing filter would''ve helped a lot. - Inspzil', '2002-12-19 07:05:04.000000', NULL, 1),
(175241, 9746, 3540, '<td valign="top">This has kind of a cool abstract feel to it. - Inspzil</td>', 'This has kind of a cool abstract feel to it. - Inspzil', '2002-12-19 07:07:51.000000', NULL, 1),
(175245, 9714, 3540, '<td valign="top">This is a cool picture.  I think it''s a little underexposed and a little too soft on the focus end of it - Inspzil</td>', 'This is a cool picture.  I think it''s a little underexposed and a little too soft on the focus end of it - Inspzil', '2002-12-19 07:10:25.000000', NULL, 1),
(175248, 9768, 3540, '<td valign="top">The colors are cool but the sky looks really pixelated to me - Inspzil</td>', 'The colors are cool but the sky looks really pixelated to me - Inspzil', '2002-12-19 07:16:30.000000', NULL, 1),
(175251, 9696, 3540, '<td valign="top">Sky could use a little more color, perhaps thru PS.  The branches and the bird don''t look particularly clear either. - Inspzil</td>', 'Sky could use a little more color, perhaps thru PS.  The branches and the bird don''t look particularly clear either. - Inspzil', '2002-12-19 07:23:00.000000', NULL, 1),
