(175468, 9753, 2983, '<td valign="top">Very nice picture.  I love the fade-off into the haze.</td>', 'Very nice picture.  I love the fade-off into the haze.', '2002-12-19 17:05:03.000000', NULL, 1),
(175473, 9810, 2983, '<td valign="top">Looks like a good climb, so maybe not untouched, but I get the idea.  Funny colors in the picture, though.</td>', 'Looks like a good climb, so maybe not untouched, but I get the idea.  Funny colors in the picture, though.', '2002-12-19 17:44:21.000000', NULL, 1),
