(176071, 9729, 4411, '<td valign="top">Excellent. Slightly disorienting when you try to figure out how it was shot. The water adds a great effect to the straightforward composition and strong colours. Must try this myself someday!</td>', 'Excellent. Slightly disorienting when you try to figure out how it was shot. The water adds a great effect to the straightforward composition and strong colours. Must try this myself someday!', '2002-12-21 19:35:18.000000', NULL, 1),
(176073, 9636, 4411, '<td valign="top">Great shot. It has a fractal quality to it which I like a lot. The almost-symmetrical composition is excellent.<br/>A shot I would like to see in full-res after the challenge.</td>', 'Great shot. It has a fractal quality to it which I like a lot. The almost-symmetrical composition is excellent.A shot I would like to see in full-res after the challenge.', '2002-12-21 19:39:31.000000', NULL, 1),
(176074, 9753, 4411, '<td valign="top">A lovely scene. I really like the composition on this. The tree taking up the right side of the frame, and the ''path'' down the middle are very strong.</td>', 'A lovely scene. I really like the composition on this. The tree taking up the right side of the frame, and the ''path'' down the middle are very strong.', '2002-12-21 19:43:40.000000', NULL, 1),
(176079, 9663, 4411, '<td valign="top">My favourite of the sunset shots. Lovely colours in the sky &amp; good strong sillouettes.</td>', 'My favourite of the sunset shots. Lovely colours in the sky & good strong sillouettes.', '2002-12-21 19:48:14.000000', NULL, 1),
(176082, 9614, 4411, '<td valign="top">A lovely ''portrait'' shot. Great composition and a good non-distracting background. I swear it''s smiling for the camera!</td>', 'A lovely ''portrait'' shot. Great composition and a good non-distracting background. I swear it''s smiling for the camera!', '2002-12-21 19:50:04.000000', NULL, 1),
