(176155, 9759, 1019, '<td valign="top">Wonderful textures with a good contrast between the wood and the leaves--focus good and composition good</td>', 'Wonderful textures with a good contrast between the wood and the leaves--focus good and composition good', '2002-12-22 01:08:26.000000', NULL, 1),
